INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(41270, 0, 0, 'Energy begins to arc across Onyxia\'s body as her electrical charge increases.', 41, 0, 100, 0, 0, 0, 'Onyxia to Onyxia'),
(41270, 1, 0, 'The arcing bolts intensify as Onyxia\'s electrical charge reaches dangerous levels!', 41, 0, 100, 0, 0, 0, 'Onyxia to Onyxia');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(41376, 0, 0, 'The air crackles with electricity!', 41, 0, 100, 0, 0, 0, 'Nefarian to Player'),
(41376, 1, 0, 'See how the shadowflame animates their bones! They fight at my command!', 14, 0, 100, 0, 0, 20073, 'Nefarian to Controller Stalker'),
(41376, 2, 0, 'Curse you, mortals! Such a callous disregard for one\'s possessions must be met with extreme force!', 14, 0, 100, 15, 0, 20155, 'Nefarian to Onyxia'),
(41376, 3, 0, 'I hope you can swim... in molten lava!', 14, 0, 100, 0, 0, 20075, 'Nefarian'),
(41376, 4, 0, 'I have tried to be an accommodating host, but you simply will not die! Time to throw all pretense aside and just... KILL YOU ALL!', 14, 0, 100, 0, 0, 20077, 'Nefarian to Nefarian'),
(41376, 5, 0, 'Flesh turns to ash!', 14, 0, 100, 0, 0, 20074, 'Nefarian'),
(41376, 6, 0, 'It has been a pleasure!', 14, 0, 100, 0, 0, 20079, 'Nefarian to Player'),
(41376, 6, 1, 'HAH!', 14, 0, 100, 0, 0, 20080, 'Nefarian to Player'),
(41376, 6, 2, 'You really have to want it!', 14, 0, 100, 0, 0, 20081, 'Nefarian to Player'),
(41376, 7, 0, 'Defeat has never tasted so bitter...', 14, 0, 100, 0, 0, 20083, 'Nefarian to Player'),
(41376, 8, 0, 'Mortal minds... So easily manipulated.', 14, 0, 100, 0, 0, 20078, 'Nefarian');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(41378, 0, 0, 'There can be no disruptions! Mustn\'t keep the master waiting! Mustn\'t fail again!', 14, 0, 100, 0, 0, 19847, 'Maloriak to Player'),
(41378, 1, 0, 'Mix and stir, apply heat...', 14, 0, 100, 0, 0, 19851, 'Maloriak to Maloriak'),
(41378, 2, 0, '|TInterface\\Icons\\INV_POTION_24.BLP:20|tMaloriak throws a |cFFFF0000red|r vial into the cauldron!', 41, 0, 100, 0, 0, 0, 'Maloriak to Maloriak'),
(41378, 2, 1, 'Strip the flesh, harvest the organs!', 14, 0, 0, 0, 0, 19849, 'VO_BD_Maloriak_event03'),
(41378, 3, 0, 'How well does the mortal shell handle extreme temperature change? Must find out! For science!', 14, 0, 100, 0, 0, 19853, 'Maloriak to Maloriak'),
(41378, 4, 0, '|TInterface\\Icons\\INV_POTION_20.BLP:20|tMaloriak throws a |cFF809FFEblue|r vial into the cauldron!', 41, 0, 100, 0, 0, 0, 'Maloriak to Maloriak'),
(41378, 5, 0, 'This one\'s a little unstable, but what\'s progress without failure?', 14, 0, 100, 0, 0, 19852, 'Maloriak to Maloriak'),
(41378, 6, 0, '|TInterface\\Icons\\INV_POTION_162.BLP:20|tMaloriak throws a |cFF33FF00green|r vial into the cauldron!', 41, 0, 100, 0, 0, 0, 'Maloriak to Maloriak'),
(41378, 7, 0, 'What they lack in intelligence they make up for in ferocity!', 14, 0, 100, 0, 0, 19856, 'Maloriak'),
(41378, 7, 1, 'My failings will be your downfall!', 14, 0, 100, 0, 0, 19857, 'Maloriak'),
(41378, 8, 0, 'Meet the brawn to my brains! Prime subjects, devour them!', 14, 0, 100, 0, 0, 19859, 'Maloriak'),
(41378, 8, 1, 'Too early, but no choice... They must be tested! Face now my prime subjects!', 14, 0, 100, 0, 0, 19858, 'Maloriak'),
(41378, 8, 2, 'When pushed to the edge, results may become unpredictable...', 14, 0, 100, 0, 0, 19854, 'Maloriak'),
(41378, 9, 0, 'Nothing goes to waste... ', 14, 0, 100, 0, 0, 19848, 'Maloriak'),
(41378, 9, 1, 'Strip the flesh, harvest the organs!', 14, 0, 100, 0, 0, 19849, 'Maloriak'),
(41378, 10, 0, 'There will never be another like me...', 14, 0, 100, 0, 0, 19850, 'Maloriak to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(41379, 0, 0, 'Ha ha ha ha ha! The heroes have made it to the glorious finale. I take it you are in good spirits? Prepared for the final battle? Then gaze now upon my ultimate creation! RISE, SISTER!', 14, 0, 100, 1, 0, 20066, 'Lord Victor Nefarius to Player'),
(41379, 1, 0, 'Behold the brood mother, Onyxia, REBORN! Perhaps my finest work.', 14, 0, 100, 22, 0, 20070, 'Lord Victor Nefarius to Player'),
(41379, 2, 0, 'My dearest sibling, do you hunger? THEN FEAST UPON OUR ENEMIES!', 14, 0, 100, 22, 0, 20071, 'Lord Victor Nefarius to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(41442, 0, 0, 'I have no need for eyes to see my enemies. Your clumsy footsteps and foul stench give you away!', 14, 0, 100, 0, 0, 20820, 'Atramedes - Aggro'),
(41442, 1, 0, '|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s rears back and casts |cFFFF0000|Hspell:77982|h[Searing Flame]|h|r!\n', 41, 0, 100, 0, 0, 0, 'Atramedes - Announce Searing Flame'),
(41442, 1, 1, 'Death waits in the darkness!', 14, 0, 0, 0, 0, 20822, 'VO_BD_ATRAMEDES aggro'),
(41442, 2, 0, 'You cannot hide from searing flame!', 14, 0, 100, 0, 0, 20826, 'Atramedes - Searing Flame'),
(41442, 3, 0, 'Yes, run! With every step your heart quickens. The beating, loud and thunderous... Almost deafening. You cannot escape!', 14, 0, 100, 0, 0, 20827, 'Atramedes - Roaring Flame Breath'),
(41442, 4, 0, 'Death waits in the darkness!', 14, 0, 100, 0, 0, 20822, 'Atramedes - Slay 1'),
(41442, 4, 1, 'Sighted, but blind to the truth. Embrace the finality of it all!', 14, 0, 100, 0, 0, 20821, 'Atramedes - Slay 2'),
(41442, 5, 0, 'This miserable existence finally ends.', 14, 0, 100, 0, 0, 20823, 'Atramedes - Death');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(41570, 0, 0, '%s begins to erupt, spewing Lava Parasites onto the ground!', 41, 0, 100, 0, 0, 8717, 'Magmaw - Announce Lava Parasites'),
(41570, 1, 0, '%s slumps forward, exposing his pincers!', 41, 0, 100, 0, 0, 8717, 'Magmaw - Announce Exposing Pincers'),
(41570, 2, 0, '%s becomes impaled on the spike, exposing his head!', 41, 0, 100, 0, 0, 8717, 'Magmaw - Announce Exposed Head');
