(42186, 0, 0, 'Electron unit activated.', 14, 0, 100, 0, 0, 21865, 'Omnotron - Activate Electron'),
(42186, 1, 0, 'Toxitron unit activated.', 14, 0, 100, 0, 0, 21867, 'Omnotron - Activate Toxitron'),
(42186, 2, 0, 'Magmatron unit activated.', 14, 0, 100, 0, 0, 21866, 'Omnotron - Activate Magmatron'),
(42186, 3, 0, 'Arcanotron unit activated.', 14, 0, 100, 0, 0, 23378, 'Omnotron - Activate Arcanotron'),
(42186, 4, 0, 'Electron unit shield systems online.', 14, 0, 100, 0, 0, 21869, 'Omnotron - Shield Electron'),
(42186, 5, 0, 'Toxitron unit shield systems online.', 14, 0, 100, 0, 0, 21871, 'Omnotron - Shield Toxitron'),
(42186, 6, 0, 'Arcanotron unit shield systems online.', 14, 0, 100, 0, 0, 21872, 'Omnotron - Shield Arcanotron'),
(42186, 7, 0, 'Magmatron unit shield systems online.', 14, 0, 100, 0, 0, 21870, 'Omnotron - Shield Magmatron'),
(42186, 8, 0, 'Rerouting excess energy to Magmatron unit. Engage flamethrower device.', 14, 0, 100, 0, 0, 21873, 'Omnotron - Magmatron Flamethrower'),
(42186, 9, 0, 'Defense systems obliterated. Powering down...', 14, 0, 100, 0, 0, 21864, 'Omnotron - Defeat'),
(42186, 10, 0, 'Rerouting excess energy to Magmatron unit. Engage flamethrower device.', 14, 0, 0, 0, 0, 21873, 'VO_BD_Council magmatron flamethrower');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43296, 0, 0, '%s snorts loudly.', 16, 0, 100, 0, 0, 0, 'Chimaeron to Player'),
(43296, 1, 0, '%s grunts and opens one eye.', 16, 0, 100, 0, 0, 0, 'Chimaeron to Player'),
(43296, 2, 0, '%s wakes up!', 16, 0, 100, 0, 0, 0, 'Chimaeron to Player'),
(43296, 3, 0, '%s prepares to massacre his foes!', 41, 0, 100, 0, 0, 0, 'Chimaeron');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(44202, 0, 0, 'A little help?', 14, 0, 100, 0, 0, 20835, 'Finkle Einhorn'),
(44202, 0, 1, 'Hey! Over here!', 14, 0, 100, 0, 0, 20834, 'Finkle Einhorn'),
(44202, 0, 2, 'Help! I\'m trapped in here!', 14, 0, 100, 0, 0, 20833, 'Finkle Einhorn'),
(44202, 1, 0, 'Poor little fella.', 14, 0, 100, 0, 0, 20836, 'Finkle Einhorn to Chimaeron'),
(44202, 2, 0, 'Great job guys! The key should be in his guts somewhere. Just, uh, fish around in there \'till you find it.', 14, 0, 100, 0, 0, 20838, 'Finkle Einhorn to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(44418, 0, 0, 'The Bile-O-Tron springs to life and begins to emit a foul smelling substance.', 16, 0, 100, 0, 0, 0, 'Bile-O-Tron 800 to Player'),
(44418, 1, 0, '|c00FF0000Chimaeron\'s Massacre has knocked the Bile-O-Tron offline!|r', 41, 0, 100, 0, 0, 0, 'Bile-O-Tron 800 to Bile-O-Tron 800'),
(44418, 2, 0, '|c0000FF00The Bile-O-Tron is back online!|r', 41, 0, 100, 0, 0, 0, 'Bile-O-Tron 800 to Bile-O-Tron 800'),
(44418, 3, 0, 'The Bile-O-Tron signals in the affirmative and shuts down permanently.', 16, 0, 100, 0, 0, 0, 'Bile-O-Tron 800 to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(49226, 0, 0, 'Hmm... the Omnotron Defense System. Centuries ago these constructs were considered the Dwarves\' greatest technical achievements. With so many counters to each construct\'s attacks, I\'ll have to rectify these designs for them to provide me any entertainment.', 14, 0, 100, 0, 0, 23374, 'Lord Victor Nefarius to Player'),
(49226, 1, 0, 'Lightning Conductor works much better in a crowd, yes?', 14, 0, 100, 0, 0, 23377, 'Lord Victor Nefarius to Player'),
(49226, 2, 0, 'Were you planning on using Toxitron\'s chemicals to damage the other constructs? Clever plan, let me ruin that for you.', 14, 0, 100, 0, 0, 23378, 'Lord Victor Nefarius to Toxitron'),
(49226, 3, 0, 'You would like to move away from that, wouldn\'t you? Too bad.', 14, 0, 100, 0, 0, 23375, 'Lord Victor Nefarius to Toxitron'),
(49226, 4, 0, 'Stupid Dwarves and your fascination with runes! Why would you create something that would help your enemy?', 14, 0, 100, 0, 0, 23376, 'Lord Victor Nefarius to Toxitron'),
(49226, 5, 0, 'Stupid Dwarves and your fascination with runes! Why would you create something that would help your enemy?', 14, 0, 0, 0, 0, 23376, 'VO_BD_Nefarian_OmnitronSpell02'),
(49226, 6, 0, 'Lightning Conductor works much better in a crowd, yes?', 14, 0, 0, 0, 0, 23377, 'VO_BD_Nefarian_OmnitronSpell03'),
(49226, 7, 0, 'Were you planning on using Toxitron\'s chemicals to damage the other constructs? Clever plan, let me ruin that for you.', 14, 0, 0, 0, 0, 23378, 'VO_BD_Nefarian_OmnitronSpell04'),
(49226, 8, 0, 'That malfunctioning piece of junk was murder on the repair bills.', 14, 0, 0, 0, 0, 20086, 'VO_BD_Nefarian_Event18'),
(49226, 9, 0, 'I found this fascinating specimen in the lava underneath this very room. Magmaw should provide an adequate challenge for your pathetic little band.', 14, 0, 0, 0, 0, 23367, 'VO_BD_Nefarian_MagmawIntro01'),
(49226, 10, 0, 'Finally someone to deal with that unsightly pest! You have my thanks, \"heroes.\"', 14, 0, 0, 0, 0, 20085, 'VO_BD_Nefarian_Event17'),
(49226, 11, 0, 'You won? How... disappointing. I could have easily watched you all continue to stand in the fire.', 14, 0, 0, 0, 0, 23366, 'VO_BD_Nefarian_MagmawDead01'),
(49226, 12, 0, 'Inconceivable! You may actually defeat my lava worm! Perhaps I can help... tip the scales. ', 14, 0, 0, 0, 0, 23368, 'VO_BD_Nefarian_MagmawLowHealth'),
(49226, 13, 0, 'On second thought, what fun is an \"adequate\" challenge?', 14, 0, 0, 0, 0, 23369, 'VO_BD_Nefarian_MagmawSummon01'),
(49226, 14, 0, 'Maloriak, try not to lose to these mortals. Semicompetent help is SO hard to create.', 14, 0, 0, 0, 0, 23372, 'VO_BD_Nefarian_MaloriakIntro01'),
(49226, 15, 0, 'Your mixtures are weak, Maloriak! They need a bit more... kick!', 14, 0, 0, 0, 0, 23370, 'VO_BD_Nefarian_Maloriak01'),
(49226, 16, 0, 'Congratulations! Allow me to grant you a title befitting the amazing achievement you just performed. Henceforth you shall be known as the \"Slayer of Stupid, Incompetent, and Disappointing Minions.\"', 14, 0, 0, 0, 0, 23371, 'VO_BD_Nefarian_MaloriakDead01'),
(49226, 17, 0, 'We never did see eye to eye... Good riddance I say!', 14, 0, 0, 0, 0, 20089, 'VO_BD_Nefarian_Event21'),
(49226, 18, 0, 'You should have been disposed of a long time ago.', 14, 0, 0, 0, 0, 23357, 'VO_BD_Nefarian_AtramedesDead'),
(49226, 19, 0, 'These shields are proving quite the nuisance.', 14, 0, 0, 0, 0, 23358, 'VO_BD_Nefarian_AtramedesGong'),
(49226, 20, 0, 'Atramedes, the heroes are right THERE!', 14, 0, 0, 0, 0, 23359, 'VO_BD_Nefarian_AtramedesImp01'),
(49226, 21, 0, 'Atramedes, are you going deaf as well as blind? Hurry up and kill them all.', 14, 0, 0, 0, 0, 23360, 'VO_BD_Nefarian_AtramedesIntro'),
(49226, 22, 0, 'Now that was really unnecessary.', 14, 0, 0, 0, 0, 20087, 'VO_BD_Nefarian_Event19'),
(49226, 23, 0, 'Impressive. You have managed to destroy one of my most horrific creations, a task I had thought impossible until now.', 14, 0, 0, 0, 0, 20088, 'VO_BD_Nefarian_Event20'),
(49226, 24, 0, 'Hmm... a shame to lose that experiment.', 14, 0, 0, 0, 0, 23361, 'VO_BD_Nefarian_ChimaronDead01'),
(49226, 25, 0, 'Ah, Chimaeron, truly a living testament to my scientific prowess. I reworked and twisted his form countless times over the years, and the final result is truly something to behold.', 14, 0, 0, 0, 0, 23362, 'VO_BD_Nefarian_ChimaronIntro01'),
(49226, 26, 0, 'Oh, you were expecting something else to happen just then, weren\'t you? Let\'s see how well YOU adapt after a new set of \"adjustments,\" shall we?', 14, 0, 0, 0, 0, 23363, 'VO_BD_Nefarian_ChimaronSpell01'),
(49226, 27, 0, 'Stop fighting yourself this instant, Chimaeron!', 14, 0, 0, 0, 0, 23364, 'VO_BD_Nefarian_ChimaronSpell02'),
(49226, 28, 0, 'This fight has gotten a bit stale; allow me to spice things up!', 14, 0, 0, 0, 0, 23365, 'VO_BD_Nefarian_ChimaronSpell03');
