INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43324, 0, 0, 'Valiona, Theralion, put them in their place.', 14, 0, 100, 0, 0, 22063, 'Cho\'gall - Theralion and Valiona Intro'),
(43324, 1, 0, '(Come closer, closer.  Let us see your faces. All will be humbled before his power.)', 14, 0, 100, 0, 0, 22064, 'Cho\'gall - Theralion and Valiona Death'),
(43324, 1, 1, 'Such is your fate.', 14, 0, 0, 0, 0, 22070, 'VO_BT_Chogall_BotEvent17'),
(43324, 1, 2, 'Pathetic flesh!', 14, 0, 0, 0, 0, 22071, 'VO_BT_Chogall_BotEvent18'),
(43324, 1, 3, '(Finish it! Finish them all!)', 14, 0, 0, 0, 0, 22072, 'VO_BT_Chogall_BotEvent19'),
(43324, 1, 4, 'Embrace your end.', 14, 0, 0, 0, 0, 22073, 'VO_BT_Chogall_BotEvent20'),
(43324, 1, 5, '(Body and soul, to be swallowed whole!)', 14, 0, 0, 0, 0, 22088, 'VO_BT_Chogall_BotEvent35'),
(43324, 1, 6, 'Now the Master has them.', 14, 0, 0, 0, 0, 22091, 'VO_BT_Chogall_BotEvent38'),
(43324, 1, 7, '(Chaos, madness! Like a hug for your brain.)', 14, 0, 0, 0, 0, 22092, 'VO_BT_Chogall_BotEvent39'),
(43324, 2, 0, 'Welcome, mortals. (Frail little children). Few have laid eyes on this inner sanctum. (They reach out to touch the fire!)', 14, 0, 100, 0, 0, 22065, 'Cho\'gall - Ascendant Council 1'),
(43324, 2, 1, 'Behold the might of the hammer!', 14, 0, 0, 0, 0, 22079, 'VO_BT_Chogall_BotEvent26'),
(43324, 2, 2, '(Stop. Hammertime!)', 14, 0, 0, 0, 0, 22080, 'VO_BT_Chogall_BotEvent27'),
(43324, 3, 0, 'It is here the chosen realize their destiny. (One with eternity). And it is here that you will realize yours.(End of the flesh. End of the flesh)!', 14, 0, 100, 0, 0, 22066, 'Cho\'gall - Ascendant Council 2'),
(43324, 4, 0, 'Brothers of Twilight! The Hammer calls to you! (Fire water earth air). Leave your mortal shell behind. (Fire water earth air). Embrace your new forms for here and everafter! (Burn and drown and crush and suffocate). And use your gifts to destroy the unbelievers. (Burn and drown and crush and suffocate)!!', 14, 0, 100, 0, 0, 22067, 'Cho\'gall - Ascendant Council 3'),
(43324, 4, 1, '(*Snort*)', 14, 0, 0, 0, 0, 22083, 'VO_BT_Chogall_BotEvent30'),
(43324, 4, 2, 'Behold the destiny of your fragile world!', 14, 0, 0, 0, 0, 22084, 'VO_BT_Chogall_BotEvent31'),
(43324, 4, 3, 'More. More!', 14, 0, 0, 0, 0, 22085, 'VO_BT_Chogall_BotEvent32'),
(43324, 4, 4, '(Come, brothers! Feast on hope!)', 14, 0, 0, 0, 0, 22086, 'VO_BT_Chogall_BotEvent33'),
(43324, 4, 5, '(More. They need more.)', 14, 0, 0, 0, 0, 22087, 'VO_BT_Chogall_BotEvent34'),
(43324, 5, 0, 'Foolish mortals-(Usurper\'s children!) nothing you have done- (Spawn of a lesser god!) I am TRYING to speak here. (Words, words, words. The Master wants murder.) ALL falls to chaos. ALL will be destroyed. (Chaos, chaos!) Your work here today changes nothing. (Chaos, chaos, all things end) No mortal may see what you have and live. Your end has come.', 14, 0, 100, 0, 0, 22068, 'Cho\'gall - Intro'),
(43324, 6, 0, 'Enough! (To His will all flesh succumbs. From His kingdom, chaos comes.) Yes - what he said.', 14, 0, 100, 0, 0, 22081, 'Cho\'gall - Aggro'),
(43324, 7, 0, 'Behold the might of the hammer!', 14, 0, 100, 0, 0, 22079, 'Cho\'gall - Absorb Fire Elemental 1'),
(43324, 7, 1, 'Give me your strength!', 14, 0, 100, 0, 0, 22078, 'Cho\'gall - Absorb Fire Elemental 1l'),
(43324, 7, 2, '(The Master\'s eye sees all that was and all to be, or not!)', 14, 0, 0, 0, 0, 22098, 'VO_BT_Chogall_BotEvent45'),
(43324, 7, 3, '(Now they see the darkness! Their eyes are open!)', 14, 0, 0, 0, 0, 22090, 'VO_BT_Chogall_BotEvent37'),
(43324, 8, 0, '(Stop. Hammertime!)', 14, 0, 100, 0, 0, 22080, 'Cho\'gall - Absorb Shadow Lorb'),
(43324, 9, 0, '|TInterface\\Icons\\ability_rogue_shadowdance.blp:20|t%s begins to summon |cFFFF0000Corrupted Adherents|r to aid him!\n', 41, 0, 100, 0, 0, 0, 'Cho\'gall - Announce Corrupting Adherents'),
(43324, 10, 0, '(*Snort*)', 14, 0, 100, 0, 0, 22083, 'Cho\'gall - Corrupting Adherents 1'),
(43324, 10, 1, '(Infinite suffering!)', 14, 0, 100, 0, 0, 22082, 'Cho\'gall - Corrupting Adherents 2'),
(43324, 10, 2, 'More. More!', 14, 0, 100, 0, 0, 22085, 'Cho\'gall - Corrupting Adherents 3'),
(43324, 10, 3, '(Come, brothers! Feast on hope!)', 14, 0, 100, 0, 0, 22086, 'Cho\'gall - Corrupting Adherents 4'),
(43324, 11, 0, 'Cho\'gall beckons and casts |cFF006EFD|Hspell:91303|h[Conversion]|h|r!', 41, 0, 100, 0, 0, 0, 'Cho\'gall - Announce Conversion'),
(43324, 12, 0, '|TInterface\\Icons\\spell_shadow_shadetruesight.blp:20|t%s begins to cast |cFFFF0000|Hspell:82299|h[Fester Blood]|h|r!', 41, 0, 100, 0, 0, 0, 'Cho\'gall - Announce Fester Blood'),
(43324, 13, 0, 'Brother, it cannot be... (Destiny has come!) My strength... (Too proud! He speaks in blood! Listen!) My mind... (It is for His glory we serve!) What... is happening... (Gone is the dawn. Come shades of Twilight. Come madness, come havoc, come Infinite Night!)', 14, 0, 100, 0, 0, 22093, 'Cho\'gall - Phase 2'),
(43324, 14, 0, '|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s begins to summon |cFFFF0000Darkened Creations|r to aid him!\n', 41, 0, 100, 0, 0, 0, 'Cho\'gall - Announce Darkened Creations'),
(43324, 15, 0, '(The claws of fate grasp the unbelievers!)', 14, 0, 100, 0, 0, 22094, 'Cho\'gall - Say Darkened Creations 1'),
(43324, 15, 1, '(The Master sees, the Master sees!)', 14, 0, 100, 0, 0, 22095, 'Cho\'gall - Say Darkened Creations 2'),
(43324, 15, 2, 'What madness have we wrought? (Not yet enough!)', 14, 0, 100, 0, 0, 22096, 'Cho\'gall - Say Darkened Creations 3'),
(43324, 15, 3, 'I...  can\'t take much more... (Brother, it merely begins!)', 14, 0, 100, 0, 0, 22097, 'Cho\'gall - Say Darkened Creations 4'),
(43324, 15, 4, '(The Master\'s eye sees all that was and all to be, or not!)', 14, 0, 100, 0, 0, 22098, 'Cho\'gall - Say Darkened Creations 5'),
(43324, 16, 0, '(Body and soul, to be swallowed whole!)', 14, 0, 100, 0, 0, 22088, 'Cho\'gall - Slay 1'),
(43324, 16, 1, 'Everyone succumbs in the end.', 14, 0, 100, 0, 0, 22089, 'Cho\'gall - Slay 1'),
(43324, 16, 2, '(Now they see the darkness! Their eyes are open!)', 14, 0, 100, 0, 0, 22090, 'Cho\'gall - Slay 1'),
(43324, 16, 3, 'Now the Master has them.', 14, 0, 100, 0, 0, 22091, 'Cho\'gall - Slay 2'),
(43324, 16, 4, '(Chaos, madness! Like a hug for your brain.)', 14, 0, 100, 0, 0, 22092, 'Cho\'gall - Slay 3'),
(43324, 16, 5, '(Blood for the master!)', 14, 0, 100, 0, 0, 22069, 'Cho\'gall - Slay 4'),
(43324, 16, 6, '(Finish it! Finish them all!)', 14, 0, 100, 0, 0, 22072, 'Cho\'gall - Slay 5'),
(43324, 17, 0, 'It is finished. (The fate of all.)', 14, 0, 100, 0, 0, 22101, 'Cho\'gall - Evade'),
(43324, 18, 0, 'Brother, we are shattered. (But the Master... I still hear... so angry... Master...?)', 14, 0, 100, 0, 0, 22099, 'Cho\'gall - Death Normal'),
(43324, 19, 0, 'Brother, we are shattered. Let her finish them. (The Master does not want them near her... Brother?  The Master seethes...)', 14, 0, 100, 0, 0, 22100, 'Cho\'gall - Death Heroic');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43686, 0, 0, 'You will die for your insolence!', 14, 0, 100, 0, 0, 20285, 'Ignacious - Engage'),
(43686, 1, 0, 'BURN!', 14, 0, 100, 0, 0, 20287, 'Ignacious - Say Aegis of Flame'),
(43686, 2, 0, '%s begins to cast Rising Flames!', 41, 0, 100, 0, 0, 0, 'Ignacious - Announce Rising Flames'),
(43686, 3, 0, 'More fuel for the fire!', 14, 0, 100, 0, 0, 20286, 'Ignacious - Slay'),
(43686, 4, 0, '...the fury of the elements!', 14, 0, 100, 0, 0, 20288, 'Ignacious - Merge');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43687, 0, 0, 'You dare invade our lord\'s sanctum?', 14, 0, 100, 0, 0, 20162, 'Feludius - Engage'),
(43687, 1, 0, 'I will freeze the blood in your veins!', 14, 0, 100, 0, 0, 20164, 'Feludius - Say Glaciate'),
(43687, 2, 0, '%s begins to cast Glaciate!', 41, 0, 100, 0, 0, 0, 'Feludius - Announce Glaciate'),
(43687, 3, 0, 'Perish!', 14, 0, 100, 0, 0, 20163, 'Feludius - Slay'),
(43687, 4, 0, 'But now, witness true power...', 14, 0, 100, 0, 0, 20165, 'Feludius - Merge');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43688, 0, 0, 'Enough of this foolishness!', 14, 0, 100, 0, 0, 20237, 'Arion - Engage'),
(43688, 1, 0, 'Wind, hear my call!', 14, 0, 100, 0, 0, 20239, 'Arion - Call Winds'),
(43688, 2, 0, '%s begins to cast Thundershock!', 41, 0, 100, 0, 0, 0, 'Arion - Announce Thundershock'),
(43688, 3, 0, 'Merely a whisper in the wind....', 14, 0, 100, 0, 0, 20238, 'Arion - Slay'),
(43688, 4, 0, 'An impressive display...', 14, 0, 100, 0, 0, 20240, 'Arion - Merge');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43689, 0, 0, 'We will handle them!', 14, 0, 100, 0, 0, 21843, 'Terrastra - Engage'),
(43689, 1, 0, 'The earth will devour you!', 14, 0, 100, 0, 0, 21844, 'Terrastra - Say Quake'),
(43689, 2, 0, '%s begins to cast Quake!', 41, 0, 100, 0, 0, 21844, 'Terrastra - Say Anounce Quake'),
(43689, 3, 0, 'The soil welcomes your bones!', 14, 0, 100, 0, 0, 21842, 'Terrastra - Slay'),
(43689, 4, 0, '...to have made it this far.', 14, 0, 100, 0, 0, 21845, 'Terrastra - Merge');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43735, 0, 0, 'BEHOLD YOUR DOOM!', 14, 0, 100, 0, 0, 20396, 'Elementium Monstrosity - Merged'),
(43735, 1, 0, 'FEEL THE POWER!', 14, 0, 100, 0, 0, 20400, 'Elementium Monstrosity - Lava Seed'),
(43735, 1, 1, 'Eradicate....', 14, 0, 0, 0, 0, 20398, 'VO_BT_Monstrosity_Event03'),
(43735, 2, 0, 'Impossible....', 14, 0, 100, 0, 0, 20399, 'Elementium Monstrosity - Death'),
(43735, 3, 0, 'Eradicate....', 14, 0, 100, 0, 0, 20398, 'Elementium Monstrosity - Slay 1'),
(43735, 3, 1, 'Annihilate....', 14, 0, 100, 0, 0, 20397, 'Elementium Monstrosity - Slay 2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(44600, 0, 0, 'Cho\'gall will have your heads! ALL OF THEM!', 14, 0, 100, 0, 0, 20186, 'Halfus Wyrmbreaker - Aggro'),
(44600, 1, 0, 'The wyrms will eat well tonight!', 14, 0, 100, 0, 0, 20187, 'Halfus Wyrmbreaker - Slay 1'),
(44600, 1, 1, 'The burden of the damned falls upon you!', 14, 0, 100, 0, 0, 20188, 'Halfus Wyrmbreaker - Slay 2'),
(44600, 2, 0, '%s binds the $n to his will!', 41, 0, 100, 0, 0, 20190, 'Halfus Wyrmbreaker - Bind Dragon'),
(44600, 3, 0, '%s roars furiously!', 41, 0, 100, 0, 0, 0, 'Halfus Wyrmbreaker - Furious Roar');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(45213, 0, 0, 'We were fools to entrust an imbecile like Cho\'gall with such a sacred duty! I will deal with you intruders myself!', 14, 0, 0, 0, 0, 20199, 'VO_BT_Sinestra_Aggro01'),
(45213, 1, 0, 'Deathwing!  I have fallen....  The brood... is lost.', 14, 0, 0, 0, 0, 20200, 'VO_BT_Sinestra_Death01'),
(45213, 2, 0, 'My brood will feed on your bones!', 14, 0, 0, 0, 0, 20201, 'VO_BT_Sinestra_Kill01'),
(45213, 2, 1, 'Powerless....', 14, 0, 0, 0, 0, 20202, 'VO_BT_Sinestra_Kill02'),
(45213, 3, 0, 'You mistake this for weakness?  Fool!', 14, 0, 0, 0, 0, 20203, 'VO_BT_Sinestra_Losing01'),
(45213, 4, 0, 'I tire of this.  Do you see this clutch amidst which you stand?  I have nurtured the spark within them, but that life-force is and always will be mine.  Behold, power beyond your comprehension!', 14, 0, 0, 0, 0, 20204, 'VO_BT_Sinestra_Phase01'),
(45213, 5, 0, 'Enough!  Drawing upon this source will set us back months.  You should feel honored to be worthy of its expenditure.  Now... die!', 14, 0, 0, 0, 0, 20206, 'VO_BT_Sinestra_Phase03'),
(45213, 6, 0, 'Feed, children!  Take your fill from their meaty husks!', 14, 0, 0, 0, 0, 20207, 'VO_BT_Sinestra_Spec01'),
(45213, 7, 0, 'The energy infused within my clutch is mine to reclaim!', 14, 0, 0, 0, 0, 20208, 'VO_BT_Sinestra_Spec02'),
(45213, 8, 0, 'Suffer!', 14, 0, 0, 0, 0, 20209, 'VO_BT_Sinestra_Spec03'),
(45213, 9, 0, 'Feel my hatred!', 14, 0, 0, 0, 0, 20210, 'VO_BT_Sinestra_Spec04'),
(45213, 10, 0, 'Come forth, children of twilight....', 14, 0, 0, 0, 0, 20211, 'VO_BT_Sinestra_Spec05'),
(45213, 11, 0, 'Your mother calls!', 14, 0, 0, 0, 0, 20212, 'VO_BT_Sinestra_Spec06');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(45992, 0, 0, 'Do as the master commands, Theralion! Kill them!', 14, 0, 100, 0, 0, 21894, 'Valiona - Intro 1'),
(45992, 1, 0, 'You are worthless, Theralion!', 14, 0, 100, 0, 0, 21895, 'Valiona - Intro 2'),
(45992, 2, 0, '|TInterface\\Icons\\spell_fire_twilightnova.blp:20|t%s casts |cFFFF0000|Hspell:86788|h[Blackout]|h|r!', 41, 0, 100, 0, 0, 0, 'Valiona'),
(45992, 3, 0, '|TInterface\\Icons\\spell_fire_twilightfire.blp:20|t%s takes a |cFFFF0000|Hspell:86059|h[Deep Breath]|h|r!', 41, 0, 100, 0, 0, 0, 'Valiona to Breath Flight Target Stalker'),
(45992, 4, 0, 'Theralion, I will engulf the hallway. Cover their escape!', 14, 0, 100, 0, 0, 21898, 'Valiona to Breath Flight Target Stalker'),
(45992, 5, 0, 'Enter Twilight!', 14, 0, 100, 0, 0, 21899, 'Valiona to Player'),
(45992, 6, 0, 'Breathe your dying breath!', 14, 0, 100, 0, 0, 21896, 'Valiona to Player'),
(45992, 7, 0, 'At least... Theralion dies with me...', 14, 0, 100, 0, 0, 21897, 'Valiona to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(45993, 0, 0, 'The master was clearly speaking to you, Valiona. I am far too busy to attack ANYONE.', 14, 0, 100, 0, 0, 20300, 'Theralion - Intro 1'),
(45993, 1, 0, 'How dare you call me worthless! You will see why I am mother\'s favored child!', 14, 0, 100, 0, 0, 20301, 'Theralion - Intro 2'),
(45993, 2, 0, 'You are not the boss of me, Valiona! I will engulf as I please!', 14, 0, 100, 0, 0, 20304, 'Theralion to Theralion Flight Target Stalker'),
(45993, 2, 1, 'There is no escape from the fury of the twilight flight!', 14, 0, 100, 0, 0, 20305, 'Theralion to Theralion Flight Target Stalker'),
(45993, 3, 0, '|TInterface\\Icons\\spell_fire_twilightpyroblast.blp:20|t%s begins to cast |cFF00EEFF|Hspell:86408|h[Dazzling Destruction]|h|r!', 41, 0, 100, 0, 0, 0, 'Theralion to Theralion Flight Target Stalker'),
(45993, 4, 0, '|TInterface\\Icons\\spell_holy_consumemagic.blp:20|t%s begins to cast |cFF00EEFF|Hspell:86622|h[Engulfing Magic]|h|r!', 41, 0, 100, 0, 0, 0, 'Theralion'),
(45993, 4, 1, 'There is no escape from the fury of the twilight flight!', 14, 0, 0, 0, 0, 20305, 'VO_BT_Theralion_Event06'),
(45993, 5, 0, 'WRITHE IN AGONY!', 14, 0, 100, 0, 0, 20306, 'Theralion to Valiona'),
(45993, 6, 0, 'Bare your soul to me, mortal.', 14, 0, 100, 0, 0, 20302, 'Theralion to Valiona'),
(45993, 7, 0, 'I knew I should have stayed out of this...', 14, 0, 100, 0, 0, 20303, 'Theralion to Valiona');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(46277, 0, 0, 'Heroes, you are not alone in this dark place!', 14, 0, 0, 0, 0, 21588, 'VO_BT_Caelestrasz_Intro01'),
(46277, 1, 0, 'Heroes!  My power wanes....', 14, 0, 0, 0, 0, 21589, 'VO_BT_Caelestrasz_Losing01'),
(46277, 2, 0, 'Sintharia, your master owes me a great debt -- one that I intend to extract from his consort\'s hide!', 14, 0, 0, 0, 0, 21590, 'VO_BT_Caelestrasz_Phase2'),
(46277, 3, 0, 'The fires dim, champions....  Take this, the last of my power.  Succeed where I have failed.  Avenge me.  Avenge the world....', 14, 0, 0, 0, 0, 21591, 'VO_BT_Caelestrasz_Phase3'),
(46277, 4, 0, 'Flame of Life!  Burn within me and renew my vigor!', 14, 0, 0, 0, 0, 21592, 'VO_BT_Caelestrasz_Recharge01'),
(46277, 5, 0, 'You are weakening, Sintharia!  Accept the inevitable!', 14, 0, 0, 0, 0, 21593, 'VO_BT_Caelestrasz_Winning01'),
(46277, 6, 0, 'All is lost....  Forgive me, my Queen....', 14, 0, 0, 0, 0, 21598, 'VO_BT_Caelestrasz_Death');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(46965, 0, 0, 'Halfus! Hear me! (The Master calls, the Master wants.) Protect our secrets, Halfus. Destroy the intruders. (Murder for His glory. Murder for His hunger.)', 14, 0, 100, 0, 0, 22055, 'Cho\'gall'),
(46965, 1, 0, ' Flesh and sinew, weak but proud. Dare they part the Master\'s shroud? They stumble fumble groping blind. Finding fate and chaos intertwined.', 14, 0, 100, 0, 0, 22056, 'Cho\'gall'),
(46965, 2, 0, 'Brothers in chaos, the Twilight has come! (Shadows lengthen, endless night.) Deathwing has sundered this world. (Doors once opened never close.) So that its true Lords may return. (The Master comes, He comes He comes.)', 14, 0, 100, 0, 0, 22057, 'Cho\'gall'),
(46965, 3, 0, 'Brothers of the Hammer, to me! (Their will is still their own.) The unbelievers still stand. Destroy them! (Crush their bodies, crush their will.)', 14, 0, 100, 0, 0, 22060, 'Cho\'gall'),
(46965, 4, 0, 'Mortals, you merely separate the wheat from the chaff. (Unworthy, unworthy).', 14, 0, 100, 0, 0, 22062, 'Cho\'gall'),
(46965, 5, 0, 'Heed His call! Cast down the heretics!', 14, 0, 0, 0, 0, 22059, 'VO_BT_Chogall_BotEvent06'),
(46965, 6, 0, 'Brothers of the Hammer, to me! (Their will is still their own.) The unbelievers still stand. Destroy them! (Crush their bodies, crush their will.)', 14, 0, 0, 0, 0, 22060, 'VO_BT_Chogall_BotEvent07'),
(46965, 7, 0, 'Mortals, you merely separate the wheat from the chaff. (Unworthy, unworthy).', 14, 0, 0, 0, 0, 22062, 'VO_BT_Chogall_BotEvent09'),
(46965, 8, 0, 'Valiona, Theralion, put them in their place.', 14, 0, 0, 0, 0, 22063, 'VO_BT_Chogall_BotEvent10'),
(46965, 9, 0, '(Come closer, closer.  Let us see your faces. All will be humbled before his power.)', 14, 0, 0, 0, 0, 22064, 'VO_BT_Chogall_BotEvent11'),
(46965, 10, 0, 'Welcome, mortals. (Frail little children). Few have laid eyes on this inner sanctum. (They reach out to touch the fire!)', 14, 0, 0, 0, 0, 22065, 'VO_BT_Chogall_BotEvent12'),
(46965, 11, 0, 'It is here the chosen realize their destiny. (One with eternity). And it is here that you will realize yours.(End of the flesh. End of the flesh)!', 14, 0, 0, 0, 0, 22066, 'VO_BT_Chogall_BotEvent13'),
(46965, 12, 0, 'Brothers of Twilight! The Hammer calls to you! (Fire water earth air). Leave your mortal shell behind. (Fire water earth air). Embrace your new forms for here and everafter! (Burn and drown and crush and suffocate). And use your gifts to destroy the unbelievers. (Burn and drown and crush and suffocate)!!', 14, 0, 0, 0, 0, 22067, 'VO_BT_Chogall_BotEvent14'),
(46965, 13, 0, 'Foolish mortals-(Usurper\'s children!) nothing you have done- (Spawn of a lesser god!) I am TRYING to speak here. (Words, words, words. The Master wants murder.) ALL falls to chaos. ALL will be destroyed. (Chaos, chaos!) Your work here today changes nothing. (Chaos, chaos, all things end) No mortal may see what you have and live. Your end has come.', 14, 0, 0, 0, 0, 22068, 'VO_BT_Chogall_BotEvent15');
